xml.Script:
        clBlue        := '0000FF';
        clRed         := 'FF0000';

        clLeftCenter  := clRed;
        clRightCenter := clBlue;


        clDots[ 0] := clRed;
        clDots[ 1] := clRed;
        clDots[ 2] := clBlue;
        clDots[ 3] := clBlue;
        clDots[ 4] := clBlue;
        clDots[ 5] := clRed;
        clDots[ 6] := clRed;
        clDots[ 7] := clBlue;
        clDots[ 8] := clBlue;
        clDots[ 9] := clBlue;


        Colors[0] := clRed;
        Colors[1] := clRed;
        Colors[2] := clBlue;
        Colors[3] := clBlue;
        Colors[4] := clRed;
        Colors[5] := clBlue;
        Colors[6] := clBlue;
        Colors[7] := clRed;
        Colors[8] := clRed;
        Colors[9] := clBlue;
        Colors[10] := clBlue;

        
        AxesAngle := 0.3;
        K := 1.2;  // Scale
        D := 0.8 * K;
        RCut := 0.88 * K;
        RCu2 := 0.5 * K;
        RCu3 := 0.5 * K;
        WBase := 0.1 * K;

        DY := 0.6 * K;

        // Rotate p around normalized v
        procedure RotatePoint(Xp, Yp, Zp, Xv, Yv, Zv, Angle);
        begin
            ca := Cos(Angle);
            sa := Sin(Angle);
            c2 := 1 - ca;

            px[i] := Xp * (Xv * c2 * Xv + ca) +
                     Yp * (Yv * c2 * Xv - sa * Zv) +
                     Zp * (Zv * c2 * Xv + sa * Yv);

            py[i] := Xp * (Xv * c2 * Yv + sa * Zv) +
                     Yp * (Yv * c2 * Yv + ca) +
                     Zp * (Zv * c2 * Yv - sa * Xv);

            pz[i] := Xp * (Xv * c2 * Zv - sa * Yv) +
                     Yp * (Yv * c2 * Zv + sa * Xv) +
                     Zp * (Zv * c2 * Zv + ca);
            Inc(i);
        end;

        cs := cos(AxesAngle);
        ss := sin(AxesAngle);

        H := D / cs;

        z := (2 * RCut - H * (cs^2 + 1)) / sqrt(3) / ss;
        Ex := cs * (z * sqrt(3) - H * ss) / 2;
        Ez := H * sqrt(3) / 2 * ss - z / 2;

        // circle
        cy := (RCut + Ez * ss / sqrt(3)) / (1 + ss^2 / 3);
        cz := cy * ss / sqrt(3);
        RC := sqrt(Ex^2 + (cy - RCut)^2 + (cz - Ez)^2) / 2.1;

        i := 0;
        RotatePoint(0, -H, -H *  ss / sqrt(3), ss, -cs, 0, Pi/3 * 0);
        RotatePoint(0, -H, -H *  ss / sqrt(3), ss, -cs, 0, Pi/3 * 1);
        RotatePoint(0, -H, -H *  ss / sqrt(3), ss, -cs, 0, Pi/3 * 2);
        RotatePoint(0, -H, -H *  ss / sqrt(3), ss, -cs, 0, Pi/3 * 3);
        RotatePoint(0, -H, -H *  ss / sqrt(3), ss, -cs, 0, Pi/3 * 4);
        RotatePoint(0, -H, -H *  ss / sqrt(3), ss, -cs, 0, Pi/3 * 5);
        RotatePoint(Ex, -RCut,  Ez, ss, -cs, 0, Pi / 3 * 0);
        RotatePoint(Ex, -RCut, -Ez, ss, -cs, 0, Pi / 3 * 0);
        RotatePoint(Ex, -RCut,  Ez, ss, -cs, 0, Pi / 3 * 1);
        RotatePoint(Ex, -RCut, -Ez, ss, -cs, 0, Pi / 3 * 1);
        RotatePoint(Ex, -RCut,  Ez, ss, -cs, 0, Pi / 3 * 2);
        RotatePoint(Ex, -RCut, -Ez, ss, -cs, 0, Pi / 3 * 2);
        RotatePoint(Ex, -RCut,  Ez, ss, -cs, 0, Pi / 3 * 3);
        RotatePoint(Ex, -RCut, -Ez, ss, -cs, 0, Pi / 3 * 3);
        RotatePoint(Ex, -RCut,  Ez, ss, -cs, 0, Pi / 3 * 4);
        RotatePoint(Ex, -RCut, -Ez, ss, -cs, 0, Pi / 3 * 4);
        RotatePoint(Ex, -RCut,  Ez, ss, -cs, 0, Pi / 3 * 5);
        RotatePoint(Ex, -RCut, -Ez, ss, -cs, 0, Pi / 3 * 5);

        for i := 0 to 17 do
            py[i] := py[i] + DY;

Figure.Script:
for i := 0 to 17 do begin
    px[i] := -px[i];
    pz[i] := -pz[i];
end;
